///
/// Supports up to 200 lines.
///
/// @since ___PKG_VERSION___
///
@mixin docblock-printer(
    $lines,
    $joiner: " / ",
    $asComment: false,
    $resistMinimize: false,
) {
    $linesListLength: list.length($lines);
    $secondChar: if( $asComment, " ", "* " );
    $secondChar_first: if( $resistMinimize, "!", if( $asComment, "", "*" ) );

    @if $linesListLength <= 0 {
        // do nothing
    } @else if $linesListLength <= 15 {
        @include _docblock-printer--max-15(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 30 {
        @include _docblock-printer--max-30(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 45 {
        @include _docblock-printer--max-45(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 60 {
        @include _docblock-printer--max-60(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 80 {
        @include _docblock-printer--max-80(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 100 {
        @include _docblock-printer--max-100(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 125 {
        @include _docblock-printer--max-125(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 150 {
        @include _docblock-printer--max-150(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else if $linesListLength <= 175 {
        @include _docblock-printer--max-175(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    } @else {
        @include _docblock-printer--max-200(
            $joiner: $joiner,
            $lines: $lines,
            $linesListLength: $linesListLength,
            $secondChar: $secondChar,
            $secondChar_first: $secondChar_first,
        );
    }
}
